"""Legacy CRMScript-compatible numeric division."""

from typing import Any


def _numeric(value: Any) -> float:
    """Apply legacy numeric-context coercion for supported operand values."""
    if value is None or value == "":
        return 0.0
    return float(value)


def safe_div(a: Any, b: Any) -> tuple[float, list[str]]:
    """Divide using Meridian CRM's division-by-zero behavior."""
    try:
        divisor = _numeric(b)
    except (TypeError, ValueError, OverflowError):
        divisor = 0.0

    if divisor == 0.0:
        return 0.0, ["SCRIPT_DIV0"]

    try:
        dividend = _numeric(a)
        return float(dividend / divisor), []
    except (TypeError, ValueError, OverflowError, ZeroDivisionError):
        return 0.0, []
